import { GameError } from '$P/platform/sdk/types.ts';
const game = {
  id: 'coin',
  validateParams(p: any) {
    if (!p || typeof p !== 'object' || Array.isArray(p) || (p.side !== 'heads' && p.side !== 'tails')) throw new GameError('INVALID_PARAMS');
    return { side: p.side };
  },
  start({ bet, params, rng }: any) {
    const outcome = rng.next() < 0.5 ? 'heads' : 'tails';
    const win = outcome === params.side;
    return { status: 'finished', state: { side: params.side, outcome, win }, payout: win ? bet * 1.96 : 0 };
  },
  action() { throw new GameError('INVALID_ACTION'); },
  publicView(s: any) { return { side: s.side, outcome: s.outcome, win: s.win }; },
};
export default game;
EOF
cat > $S/ui/index.html <<'EOF'
<!doctype html><meta charset="utf-8"><title>Монетка</title>
<body><div data-testid="game" data-state="idle">
<span data-testid="balance"></span><input data-testid="bet-input" value="1">
<button data-testid="side-heads" aria-pressed="true">Орёл</button><button data-testid="side-tails" aria-pressed="false">Решка</button>
<button data-testid="play">Бросить</button><span data-testid="outcome"></span><span data-testid="payout"></span><span data-testid="error"></span></div>
<script src="/sdk.js"></script>
<script>
const q = (id) => document.querySelector('[data-testid="' + id + '"]');
let side = 'heads';
function pick(s) { side = s; q('side-heads').setAttribute('aria-pressed', String(s === 'heads')); q('side-tails').setAttribute('aria-pressed', String(s === 'tails')); }
q('side-heads').addEventListener('click', () => pick('heads'));
q('side-tails').addEventListener('click', () => pick('tails'));
PlatformSDK.open().then((o) => { q('balance').textContent = o.balance.toFixed(2); });
q('play').addEventListener('click', async () => {
  q('play').disabled = true; q('error').textContent = ''; const prev = q('game').dataset.state; q('game').dataset.state = 'playing';
  try {
    const r = await PlatformSDK.startRound(Number(q('bet-input').value), { side });
    q('outcome').textContent = r.view.outcome === 'heads' ? 'Орёл' : 'Решка';
    q('payout').textContent = r.payout.toFixed(2); q('balance').textContent = r.balance.toFixed(2);
    q('game').dataset.state = r.view.win ? 'won' : 'lost';
  } catch (e) { q('error').textContent = e.code; q('game').dataset.state = prev; }
  q('play').disabled = false;
});
</script>
EOF
